// Registers the merge drivers that .gitattributes names (margo-derived, margo-ratchet) in this repository's git config.
// The config lives in the shared .git/config, so one run covers the main checkout and every worktree.
// Usage: node scripts/setup-merge-drivers.mjs   (scripts/worktree-node-modules.mjs runs it for a new worktree)
// Without the registration git falls back to its text merge and the generated files conflict as before.
import { execFileSync } from 'node:child_process';
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const DRIVERS = {
  'margo-derived': 'Generated records (kept as on main, regenerated by land-records)',
  'margo-ratchet': 'Quality baselines (limits only shrink)',
};

/**
 * Writes the driver entries of git config in `cwd` that are missing or differ. The command is relative: git runs drivers
 * at the work tree root. An entry already right is not written: every worktree shares one .git/config, and on Windows any
 * git command in any worktree that reads it during the rename of a write dies with "unable to access '.git/config':
 * Permission denied". Every new worktree runs this.
 */
export function setupMergeDrivers(cwd = process.cwd()) {
  const git = (...args) => execFileSync('git', args, { cwd, encoding: 'utf8' }).trim(),
    set = (key, value) => {
      if (git('config', '--get', '--default', '', key) !== value) git('config', key, value);
    };
  for (const [name, description] of Object.entries(DRIVERS)) {
    set(`merge.${name}.name`, description);
    set(`merge.${name}.driver`, `node scripts/merge-driver.mjs ${name.slice(6)} %O %A %B`);
  }
  installQueueHook(git, cwd);
}

/**
 * Puts the never-more-than-6 hook in the hooks folder every worktree shares, with LF line ends whatever the checkout has:
 * sh reads a CR as part of the command. Unchanged content is not written again.
 */
function installQueueHook(git, cwd) {
  const source = resolve(dirname(fileURLToPath(import.meta.url)), 'hooks/reference-transaction'),
    target = resolve(cwd, git('rev-parse', '--git-path', 'hooks/reference-transaction')),
    body = readFileSync(source, 'utf8').replace(/\r\n/g, '\n');
  if (existsSync(target) && readFileSync(target, 'utf8') === body) return;
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, body);
  chmodSync(target, 0o755);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  setupMergeDrivers();
  console.log(`merge drivers registered: ${Object.keys(DRIVERS).join(', ')}`);
}
